const input = $input.first().json;
const body = input.body || input;

const prompt = `You are an expert email marketing copywriter. Generate email copy based on these parameters:

Purpose: ${body.purpose || 'promotional'}
Tone: ${body.tone || 'professional'}
Audience: ${body.audience || 'B2B decision makers'}
Product/Service: ${body.product || 'marketing automation platform'}
Key Message: ${body.key_message || ''}
CTA: ${body.cta || 'Schedule a demo'}
Language: ${body.language || 'Indonesian'}

Generate:
1. 3 subject line options (max 60 chars each)
2. Preview text (max 90 chars)
3. Email body (150-250 words)
4. CTA button text

Format as JSON with keys: subject_lines (array), preview_text, body_html, cta_text`;

return [{ json: { prompt, params: body, client_id: body.client_id } }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';

let generated = {};
try {
  // Try to parse JSON from response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  generated = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch(e) {
  generated = {
    subject_lines: ['Generated subject line'],
    preview_text: 'Preview text',
    body_html: content,
    cta_text: 'Learn More'
  };
}

return [{ json: {
  success: true,
  generated: generated,
  usage: {
    prompt_tokens: response.usage?.prompt_tokens || 0,
    completion_tokens: response.usage?.completion_tokens || 0,
    total_tokens: response.usage?.total_tokens || 0
  },
  model: response.model || 'unknown'
}}];
